<?php
declare(strict_types=1); require __DIR__.'/includes/auth_guard.php';
$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1){flash('danger','Invalid room ID.');redirect('new_buildingAdmin.php');}$row=$roomModel->find($id);if(!$row){flash('danger','Room not found.');redirect('new_buildingAdmin.php');}$errors=[];$data=$row;
if($_SERVER['REQUEST_METHOD']==='POST'){$data=array_merge($data,$_POST);$bid=filter_var($_POST['bid']??null,FILTER_VALIDATE_INT);$roomnum=trim((string)($_POST['roomnum']??''));$floor=trim((string)($_POST['floor']??''));$desc=trim((string)($_POST['descriptions']??''));if(!verify_csrf($_POST['csrf_token']??null))$errors[]='Invalid form token.';if($bid===false||$bid===null||$bid<1||!$buildingModel->exists($bid))$errors[]='Building ID is invalid or does not exist.';if($roomnum==='')$errors[]='Room number is required.';if($floor==='')$errors[]='Floor is required.';if(!$errors){$newImage=null;try{$newImage=image_upload();$roomModel->update($id,$bid,$roomnum,$floor,$desc,$newImage);if($newImage)delete_uploaded_image((string)$row['imgroom']);flash('success','Room updated successfully.');redirect('new_buildingAdmin.php');}catch(Throwable $e){error_log($e->getMessage());if($newImage)delete_uploaded_image($newImage);$errors[]='The room could not be updated.';}}}
$pageTitle='Edit Room';require __DIR__.'/includes/admin_header.php';
?><div class="admin-card form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php foreach($errors as $error):?><div class="alert alert-danger"><?=e($error)?></div><?php endforeach;?><div class="mb-3"><label class="form-label">Building ID</label><input class="form-control" type="number" name="bid" value="<?=e((string)$data['bid'])?>" required></div><div class="mb-3"><label class="form-label">Room number</label><input class="form-control" name="roomnum" value="<?=e((string)$data['roomnum'])?>" required></div><div class="mb-3"><label class="form-label">Floor</label><input class="form-control" name="floor" value="<?=e((string)$data['floor'])?>" required></div><div class="mb-3"><label class="form-label">Current image</label><br><img class="current-image" src="<?=e((string)$row['imgroom'])?>" alt="Current room image"></div><div class="mb-3"><label class="form-label">Replace image (optional)</label><input class="form-control" type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"></div><div class="mb-3"><label class="form-label">Description</label><textarea class="form-control" name="descriptions" rows="8"><?=e((string)$data['descriptionOfRoom'])?></textarea></div><button class="btn btn-success">Update</button> <a class="btn btn-secondary" href="new_buildingAdmin.php">Cancel</a></form></div><?php require __DIR__.'/includes/admin_footer.php';?>
